package com.quicknotes.app;
import android.appwidget.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
public class WidgetService extends RemoteViewsService {
 @Override public RemoteViewsFactory onGetViewFactory(Intent i){return new Factory(this,i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1));}
 static class Factory implements RemoteViewsFactory {final Context c;final int id;List<JSONObject> rows=new ArrayList<>();Factory(Context c,int id){this.c=c;this.id=id;}public void onCreate(){onDataSetChanged();}public void onDataSetChanged(){rows=ReminderWidget.rows(c,ReminderWidget.prefs(c).getString(id+"list","all"));}public void onDestroy(){rows.clear();}public int getCount(){return rows.size();}public RemoteViews getViewAt(int p){if(p<0||p>=rows.size())return null;JSONObject i=rows.get(p);RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_row);boolean dark=ReminderWidget.dark(c,id);r.setTextViewText(R.id.row_title,(i.optBoolean("urgent")?"⏰ ":"")+(i.optBoolean("flag")?"⚑ ":"")+i.optString("title"));r.setTextColor(R.id.row_title,dark?0xffeeeeee:0xff222222);long due=i.optLong("due");String text=due==0?"No due date":(i.optBoolean("timeEnabled")?java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT):java.text.DateFormat.getDateInstance(java.text.DateFormat.SHORT)).format(new Date(due));r.setTextViewText(R.id.row_due,text);r.setTextColor(R.id.row_due,due>0&&due<System.currentTimeMillis()?0xffe53935:dark?0xffbbbbbb:0xff666666);r.setOnClickFillInIntent(R.id.widget_row,new Intent().putExtra("reminderId",i.optString("id")));return r;}public RemoteViews getLoadingView(){return null;}public int getViewTypeCount(){return 1;}public long getItemId(int p){return p;}public boolean hasStableIds(){return false;}}
}
